package test;

import org.eclipse.jdt.core.IModuleDescription;

public class NegativeTestClass {

    // This method already uses the modern API, should not be touched.
    public boolean checkModernModule(IModuleDescription module) {
        if (module != null && module.isSystemModule()) {
            return true;
        }
        return false;
    }

    // This method uses a different 'isSystemModule' or type, should not be touched.
    public boolean checkOtherModule(MyCustomModule customModule) {
        if (customModule != null && customModule.isSystemModule()) {
            return true;
        }
        return false;
    }
}

// A custom class with a method of the same name but different context.
class MyCustomModule {
    public boolean isSystemModule() {
        return false;
    }
}
